-- Synthetic minimal baseline; not a dump of production schema.
create role anon;create role authenticated;create role service_role bypassrls;create schema auth;create table auth.users(id uuid primary key);create function auth.uid() returns uuid language sql as 'select nullif(current_setting(''request.jwt.claim.sub'',true),'''')::uuid';grant usage on schema auth to authenticated;grant execute on function auth.uid() to authenticated;insert into auth.users values('10000000-0000-4000-8000-000000000001'),('10000000-0000-4000-8000-000000000002');
 create table uploads(id uuid primary key default gen_random_uuid(),user_id uuid references auth.users,filename text,line_item_count int,total_amount numeric,pass1_status text,pass2_status text,uploaded_at timestamptz default now(),health_score numeric,ai_analysis jsonb);
 create table line_items(id uuid primary key default gen_random_uuid(),upload_id uuid references uploads,raw_text text,vendor text,amount numeric not null,transaction_date date,category text,subcategory text,confidence numeric,is_anomaly boolean,anomaly_severity text,is_first_time_vendor boolean,is_round_number boolean,is_possible_duplicate boolean,user_resolution text,z_score numeric);
 create table vendors(id uuid primary key default gen_random_uuid(),user_id uuid,vendor_name text,total_occurrences int,total_spend numeric,avg_amount numeric,recurrence_tier text,primary_category text,first_seen_upload_id uuid references uploads,last_seen_upload_id uuid references uploads);
 create table category_stats(id uuid primary key default gen_random_uuid(),upload_id uuid references uploads,category text,computed_at timestamptz default now(),total_spend_period numeric,total_spend_alltime numeric,mean_amount numeric,median_amount numeric,std_dev numeric,rolling_avg_5 numeric,rolling_avg_alltime numeric,pct_of_total_spend numeric,trend_direction text);
